import { gsap } from 'gsap';
import { MeshBasicNodeMaterial, Group, Mesh } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new Group();
  group.position.fromArray(config.scenePosition || [0, 0, 0]);

  let glbScene = null;
  let hoverTimeline = null;
  let pressTimeline = null;

  // Load GLB mesh
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    glbScene = gltf.scene;
    group.add(glbScene);

    // Scale and position the mesh within the card
    glbScene.scale.set(1, 1, 1);
    glbScene.position.set(0, 0, 0);
  });

  // Hover interaction: subtle rise-in (0.15 units)
  const onHover = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(group.position, {
      y: group.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  const onHoverOut = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(group.position, {
      y: config.scenePosition?.[1] ?? 0,
      duration: 0.5,
      ease: 'power2.out',
    });
  };

  // Press interaction: scale down briefly
  const onMouseDown = () => {
    if (pressTimeline) pressTimeline.kill();
    pressTimeline = gsap.timeline();
    pressTimeline.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out',
    });
  };

  const onMouseUp = () => {
    if (pressTimeline) pressTimeline.kill();
    pressTimeline = gsap.timeline();
    pressTimeline.to(group.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.2,
      ease: 'back.out',
    });
  };

  // Click interaction: emit event
  const onClick = () => {
    ctx.emit('hub-home.select', { cardId: config.id || 'home-thumbnail' });
  };

  // Attach event handlers
  group.userData.handlers = {
    hover: onHover,
    hoverOut: onHoverOut,
    mouseDown: onMouseDown,
    mouseUp: onMouseUp,
    click: onClick,
  };

  // Cleanup function
  group.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    if (pressTimeline) pressTimeline.kill();

    // Dispose geometries and materials
    group.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach((mat) => mat.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return group;
}
